    "使用 Claude Code 分析，需要在這台電腦安裝 Claude Code 命令列工具，並登入付費的 Claude 帳號（Pro、Max、Team 或 Enterprise；免費方案不含 Claude Code）。": "使用 Claude Code 分析，需要在這台電腦安裝 Claude Code 命令列工具，並登入付費的 Claude 帳號（Pro、Max、Team 或 Enterprise；免費方案不含 Claude Code）。",
