    "等到 PowerShell 不再輸出文字、又出現可以輸入的提示時，就代表裝好了。不需要關掉 PowerShell，也不用設定 PATH。": "等到 PowerShell 不再輸出文字、又出現可以輸入的提示時，就代表裝好了。不需要關掉 PowerShell，也不用設定 PATH。",
    "等到終端機不再輸出文字、又出現可以輸入的提示時，就代表裝好了。不需要關掉終端機，也不用設定 PATH。": "等到終端機不再輸出文字、又出現可以輸入的提示時，就代表裝好了。不需要關掉終端機，也不用設定 PATH。",
