    "如果還是顯示找不到 Codex，在同一個視窗執行這行：出現版本號就代表已裝好，請再按一次「重新檢查」；出現錯誤則代表沒裝成功，請重做第 1 步，並留意紅色的錯誤訊息。": "如果還是顯示找不到 Codex，在同一個視窗執行這行：出現版本號就代表已裝好，請再按一次「重新檢查」；出現錯誤則代表沒裝成功，請重做第 1 步，並留意紅色的錯誤訊息。",
    "如果這行也顯示找不到，代表還沒裝好：請重做第 1 步，並留意紅色的錯誤訊息。": "如果這行也顯示找不到，代表還沒裝好：請重做第 1 步，並留意紅色的錯誤訊息。",
