    "安裝完成後，關閉這個 PowerShell，再開一個新的視窗（新視窗才會用到更新後的 PATH），執行登入指令並依瀏覽器指示完成授權：": "安裝完成後，關閉這個 PowerShell，再開一個新的視窗（新視窗才會用到更新後的 PATH），執行登入指令並依瀏覽器指示完成授權：",
    "安裝完成後，開一個新的終端機視窗，執行登入指令並依瀏覽器指示完成授權：": "安裝完成後，開一個新的終端機視窗，執行登入指令並依瀏覽器指示完成授權：",
