    "請重新輸入並儲存 BingX 金鑰以恢復同步。舊加密資料已保留；之後同步不再要求系統密碼。": "Re-enter and save BingX credentials to resume syncing. Previous encrypted data is preserved; future syncs do not request your system password.",
    "已記錄過金鑰設定；按下「同步持倉」時才確認已儲存金鑰，也可在此重新儲存。": "Previous credential setup is recorded. Saved credentials are checked when you select Sync positions. You can also save them again here.",
