    "請重新輸入並儲存 Jev 金鑰以恢復分類。舊加密資料已保留。": "Re-enter and save your Jev key to resume classification. Previous encrypted data is preserved.",
    "舊金鑰尚未確認，新聞分類暫停。請重新輸入並儲存金鑰後啟用。": "The old key is unverified, so news classification is paused. Re-enter and save the key to enable it.",
