    "JBlanked 經濟日曆": "JBlanked economic calendar",
    "提供經濟日曆來源檢查使用。儲存金鑰不會立即呼叫供應商；檢查仍受既有請求額度限制。": "Used to check economic-calendar coverage. Saving a key does not call the provider immediately. Checks remain subject to existing request limits.",
    "請重新輸入並儲存金鑰以啟用此連線。舊加密資料已保留。": "Re-enter and save the key to enable this connection. Previous encrypted data is preserved.",
