    "交易偏好、持倉、最愛、金鑰與本應用程式的登入授權保存在本機 SQLite，不再使用系統金鑰圈。資料庫與備份包含可還原的連線資料，請勿分享。AI 分析與新聞分類仍需連網。": "Trading preferences, positions, favorites, credentials, and this application's authorization are stored in local SQLite, without the system keychain. The database and backups contain recoverable connection data; do not share them. AI analysis and news classification still require an internet connection.",
