    "電腦": "Computer",
    "電腦上找不到這筆資料，或 App 正在更新。": "Your computer could not find this, or the app is updating.",
    "電腦上的 txinTrade 版本不支援這個操作，請更新 App。": "The txinTrade version on your computer does not support this. Please update the app.",
